solution:
def import_points(text):
    import csv
    import io

    reader = csv.DictReader(io.StringIO(text))
    if not {"team", "points"}.issubset(reader.fieldnames or []):
        raise ValueError("team and points headers required")
    totals = {}
    accepted = rejected = 0
    for row in reader:
        team = (row.get("team") or "").strip()
        try:
            points = int(row.get("points") or "")
        except ValueError:
            rejected += 1
            continue
        if not team or points < 0:
            rejected += 1
            continue
        totals[team] = totals.get(team, 0) + points
        accepted += 1
    return {
        "accepted": accepted,
        "rejected": rejected,
        "totals": dict(sorted(totals.items())),
    }

alternative:
def import_points(text):
    from csv import DictReader
    from io import StringIO

    reader = DictReader(StringIO(text))
    if any(key not in (reader.fieldnames or []) for key in ("team", "points")):
        raise ValueError("missing headers")
    valid = []
    invalid = 0
    for row in reader:
        try:
            name = (row.get("team") or "").strip()
            count = int(row.get("points") or "")
            if not name or count < 0:
                raise ValueError("bad row")
        except ValueError:
            invalid += 1
        else:
            valid.append((name, count))
    result = {}
    for name, count in valid:
        result[name] = result.get(name, 0) + count
    return dict(
        accepted=len(valid),
        rejected=invalid,
        totals={key: result[key] for key in sorted(result)},
    )

checks:
assert s.import_points("team,points\nb,2\na,3\nb,4\n,1\nc,no\na,-1\n") == {
    "accepted": 3,
    "rejected": 3,
    "totals": {"a": 3, "b": 6},
}, "Reconcile good and invalid rows"
assert s.import_points("team,points\n") == {
    "accepted": 0,
    "rejected": 0,
    "totals": {},
}, "Header-only batch"
assert list(s.import_points("team,points\nz,0\na,1\n")["totals"]) == ["a", "z"], (
    "Deterministic key order"
)
assert s.import_points('team,points\n"a,b",2\n')["totals"] == {"a,b": 2}, (
    "Honor CSV quoting"
